package com.cinenest.rooms.internal;
import java.time.*;import java.sql.ResultSet;import java.sql.SQLException;import java.util.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;
@Repository
class JdbcBannerRepository implements BannerRepository {
 final JdbcClient jdbc;JdbcBannerRepository(JdbcClient jdbc){this.jdbc=jdbc;}
 public boolean venueVisible(UUID v){return jdbc.sql("SELECT count(*) FROM cinenest_rooms.venue v WHERE v.venue_id=:v AND v.enabled AND v.cleaning_buffer_minutes IS NOT NULL AND EXISTS(SELECT 1 FROM cinenest_rooms.venue_operating_window w WHERE w.venue_id=v.venue_id)").param("v",v).query(Integer.class).single()>0;}
 public Instant now(){return jdbc.sql("SELECT clock_timestamp()").query((r,n)->r.getTimestamp(1).toInstant()).single();}
 public void commandLock(UUID a,UUID c){jdbc.sql("SELECT pg_advisory_xact_lock(hashtextextended(:key,0))").param("key",a+":"+c).query((r,n)->true).single();}
 public Optional<Command> command(UUID a,UUID c){return jdbc.sql("SELECT * FROM cinenest_rooms.banner_command WHERE actor_id=:a AND command_id=:c").param("a",a).param("c",c).query((r,n)->new Command(r.getObject("banner_id",UUID.class),r.getObject("venue_id",UUID.class),r.getString("action"),r.getString("request_hash"),r.getLong("result_revision"))).optional();}
 Banner read(ResultSet r)throws SQLException{return new Banner(r.getObject("banner_id",UUID.class),r.getObject("venue_id",UUID.class),r.getLong("resource_revision"),r.getLong("draft_revision"),(Long)r.getObject("published_revision"));}
 public Banner banner(UUID v,UUID id,boolean lock){return jdbc.sql("SELECT * FROM cinenest_rooms.banner WHERE venue_id=:v AND banner_id=:id"+(lock?" FOR UPDATE":"")).param("v",v).param("id",id).query((r,n)->read(r)).optional().orElseThrow(()->new RoomFailure(404,"Banner unavailable"));}
 public List<Banner> list(UUID v){return jdbc.sql("SELECT * FROM cinenest_rooms.banner WHERE venue_id=:v ORDER BY banner_id LIMIT 100").param("v",v).query((r,n)->read(r)).list();}
 Revision rev(ResultSet r)throws SQLException{return new Revision(r.getLong("revision_number"),new BannerPolicy.Content(r.getString("title"),r.getString("description"),r.getString("alt_text"),r.getString("asset_id"),r.getInt("asset_version"),r.getTimestamp("starts_at").toInstant(),r.getTimestamp("ends_at").toInstant(),r.getInt("display_order"),r.getString("link_target")),r.getObject("author_id",UUID.class),r.getString("review_hash"),r.getString("asset_sha256"));}
 public Revision revision(UUID id,long number){return jdbc.sql("SELECT * FROM cinenest_rooms.banner_revision WHERE banner_id=:id AND revision_number=:n").param("id",id).param("n",number).query((r,n)->rev(r)).single();}
 public List<Revision> history(UUID id){return jdbc.sql("SELECT * FROM cinenest_rooms.banner_revision WHERE banner_id=:id ORDER BY revision_number DESC LIMIT 100").param("id",id).query((r,n)->rev(r)).list();}
 public void create(Banner b){jdbc.sql("INSERT INTO cinenest_rooms.banner VALUES(:id,:v,1,1,NULL)").param("id",b.id()).param("v",b.venue()).update();}
 public void update(Banner b){jdbc.sql("UPDATE cinenest_rooms.banner SET resource_revision=:r,draft_revision=:d,published_revision=:p WHERE banner_id=:id").param("id",b.id()).param("r",b.version()).param("d",b.draft()).param("p",b.published(),java.sql.Types.BIGINT).update();}
 public void revision(Banner b,Revision r){var c=r.content();jdbc.sql("INSERT INTO cinenest_rooms.banner_revision(banner_id,venue_id,revision_number,title,description,alt_text,asset_id,asset_version,asset_sha256,starts_at,ends_at,display_order,link_target,author_id,review_hash) VALUES(:id,:v,:n,:t,:d,:alt,:asset,1,:sha,:s,:e,:o,:l,:a,:h)").param("id",b.id()).param("v",b.venue()).param("n",r.number()).param("t",c.title()).param("d",c.description()).param("alt",c.altText()).param("asset",c.assetId()).param("sha",r.assetHash()).param("s",OffsetDateTime.ofInstant(c.startsAt(),ZoneOffset.UTC)).param("e",OffsetDateTime.ofInstant(c.endsAt(),ZoneOffset.UTC)).param("o",c.displayOrder()).param("l",c.linkTarget()).param("a",r.author()).param("h",r.hash()).update();}
 public UUID audit(UUID a,UUID v,UUID id,String action,String outcome,long before,long after){UUID event=UUID.randomUUID();jdbc.sql("INSERT INTO cinenest_rooms.banner_audit(event_id,actor_id,venue_id,banner_id,action,outcome,revision_before,revision_after,correlation_id) VALUES(:event,:a,:v,:id,:action,:outcome,:before,:after,:correlation)").param("event",event).param("a",a).param("v",v).param("id",id,java.sql.Types.OTHER).param("action",action).param("outcome",outcome).param("before",before).param("after",after).param("correlation",UUID.randomUUID()).update();return event;}
 public void command(UUID a,UUID c,UUID v,UUID id,String action,String hash,long result,UUID audit){jdbc.sql("INSERT INTO cinenest_rooms.banner_command VALUES(:a,:c,:v,:id,:action,:h,:r,:audit)").param("a",a).param("c",c).param("v",v).param("id",id).param("action",action).param("h",hash).param("r",result).param("audit",audit).update();}
 public List<Banner> live(UUID v){return jdbc.sql("SELECT b.* FROM cinenest_rooms.banner b JOIN cinenest_rooms.banner_revision r ON r.banner_id=b.banner_id AND r.revision_number=b.published_revision JOIN cinenest_rooms.venue v ON v.venue_id=b.venue_id WHERE v.enabled AND v.cleaning_buffer_minutes IS NOT NULL AND EXISTS(SELECT 1 FROM cinenest_rooms.venue_operating_window w WHERE w.venue_id=v.venue_id) AND (:all OR b.venue_id=:v) AND r.starts_at<=statement_timestamp() AND r.ends_at>statement_timestamp() ORDER BY r.display_order,b.venue_id,b.banner_id LIMIT 100").param("all",v==null).param("v",v,java.sql.Types.OTHER).query((r,n)->read(r)).list();}
}
